package com.muyuchat.core.engine.contract

/**
 * Type of callback event emitted during request execution.
 */
enum class CallbackEventType {
    Token,
    Progress,
    Preview,
    StateChanged,
    Error,
    Terminal,
    Heartbeat
}

/**
 * Origin subsystem of the callback event.
 */
enum class CallbackSource {
    Native,
    Engine,
    Worker,
    System
}

/**
 * Marker interface for typed callback event payloads.
 */
sealed interface CallbackPayload

/**
 * Streaming text token generated by LLM runtime.
 */
data class TokenPayload(
    val text: String,
    val index: Long,
    val isSpecial: Boolean = false
) : CallbackPayload

/**
 * Execution progress milestone.
 */
data class ProgressPayload(
    val current: Float,
    val total: Float,
    val stage: String,
    val detail: String = ""
) : CallbackPayload {
    val percentage: Float
        get() = if (total > 0f) (current / total).coerceIn(0f, 1f) * 100f else 0f
}

/**
 * Preview image frame generated during diffusion or vision tasks.
 */
data class PreviewPayload(
    val frameIndex: Int,
    val width: Int,
    val height: Int,
    val format: String,
    val dataSha256: String
) : CallbackPayload

/**
 * Notification of an internal lifecycle state change.
 */
data class StatePayload(
    val previousState: RequestState,
    val newState: RequestState
) : CallbackPayload

/**
 * Execution error event.
 */
data class ErrorPayload(
    val error: ErrorEnvelope
) : CallbackPayload

/**
 * Irreversible terminal completion event.
 */
data class TerminalPayload(
    val finalState: RequestState,
    val totalTokens: Long = 0L,
    val elapsedMs: Long = 0L
) : CallbackPayload {
    init {
        require(finalState.isTerminal) { "TerminalPayload finalState must be terminal: $finalState" }
    }
}

/**
 * Heartbeat liveness event.
 */
data class HeartbeatPayload(
    val timestampMs: Long
) : CallbackPayload

/**
 * Unified callback event contract for streaming and lifecycle notifications.
 *
 * Emitted across Native/JNI and engine layers, routed via CallbackRouter to consumers.
 */
data class CallbackEvent(
    val identity: RequestIdentity,
    val eventType: CallbackEventType,
    val sequence: Long,
    val monotonicTimeMs: Long,
    val payload: CallbackPayload,
    val isTerminal: Boolean,
    val source: CallbackSource,
    val diagnosticContext: Map<String, String> = emptyMap()
) {
    init {
        require(sequence >= 0L) { "sequence must be non-negative: $sequence" }
        require(monotonicTimeMs >= 0L) { "monotonicTimeMs must be non-negative: $monotonicTimeMs" }
        if (isTerminal) {
            require(eventType == CallbackEventType.Terminal || eventType == CallbackEventType.Error) {
                "Only Terminal or Error events may have isTerminal=true: $eventType"
            }
        }
    }

    /**
     * Checks if this event is stale relative to current active epoch, generation, and worker.
     */
    fun isStaleFor(
        activeEpoch: Long,
        activeGeneration: Long,
        activeWorker: Long
    ): Boolean = identity.isStaleComparedTo(activeEpoch, activeGeneration, activeWorker)

    /**
     * Diagnostic string representation.
     */
    fun toDiagnosticString(): String =
        "CallbackEvent[id=${identity.requestId}, type=$eventType, seq=$sequence, src=$source, term=$isTerminal, tMs=$monotonicTimeMs]"

    companion object {
        fun token(
            identity: RequestIdentity,
            sequence: Long,
            text: String,
            tokenIndex: Long,
            monotonicTimeMs: Long = System.nanoTime() / 1_000_000L,
            source: CallbackSource = CallbackSource.Native
        ): CallbackEvent = CallbackEvent(
            identity = identity,
            eventType = CallbackEventType.Token,
            sequence = sequence,
            monotonicTimeMs = monotonicTimeMs,
            payload = TokenPayload(text, tokenIndex),
            isTerminal = false,
            source = source
        )

        fun progress(
            identity: RequestIdentity,
            sequence: Long,
            current: Float,
            total: Float,
            stage: String,
            monotonicTimeMs: Long = System.nanoTime() / 1_000_000L,
            source: CallbackSource = CallbackSource.Native
        ): CallbackEvent = CallbackEvent(
            identity = identity,
            eventType = CallbackEventType.Progress,
            sequence = sequence,
            monotonicTimeMs = monotonicTimeMs,
            payload = ProgressPayload(current, total, stage),
            isTerminal = false,
            source = source
        )

        fun terminal(
            identity: RequestIdentity,
            sequence: Long,
            finalState: RequestState,
            totalTokens: Long = 0L,
            elapsedMs: Long = 0L,
            monotonicTimeMs: Long = System.nanoTime() / 1_000_000L,
            source: CallbackSource = CallbackSource.Native
        ): CallbackEvent = CallbackEvent(
            identity = identity,
            eventType = CallbackEventType.Terminal,
            sequence = sequence,
            monotonicTimeMs = monotonicTimeMs,
            payload = TerminalPayload(finalState, totalTokens, elapsedMs),
            isTerminal = true,
            source = source
        )

        fun error(
            identity: RequestIdentity,
            sequence: Long,
            error: ErrorEnvelope,
            monotonicTimeMs: Long = System.nanoTime() / 1_000_000L,
            source: CallbackSource = CallbackSource.Native
        ): CallbackEvent = CallbackEvent(
            identity = identity,
            eventType = CallbackEventType.Error,
            sequence = sequence,
            monotonicTimeMs = monotonicTimeMs,
            payload = ErrorPayload(error),
            isTerminal = true,
            source = source
        )
    }
}
